<?php
session_start();
require '../../includes/conexao.php';
require '../../includes/verificar_sessao.php';
verificar_perfil('Coordenação');
function esc($v) { return htmlspecialchars((string)$v, ENT_QUOTES, 'UTF-8'); }
function fmt($v, $dec = 1) { return number_format((float)$v, $dec, ',', '.'); }
$turmas = [];
$res = $conexao->query('SELECT id_turma, nome, ano_letivo FROM turma ORDER BY ano_letivo DESC, nome');
if ($res) { while ($r = $res->fetch_assoc()) $turmas[] = $r; $res->free(); }
$id_turma = max(0, (int)($_GET['turma'] ?? 0));
$turma_valida = $id_turma === 0;
foreach ($turmas as $t) if ((int)$t['id_turma'] === $id_turma) $turma_valida = true;
if (!$turma_valida) $id_turma = 0;
$nota_limite = isset($_GET['nota']) && is_numeric($_GET['nota']) ? max(0, min(10, (float)$_GET['nota'])) : 6.0;
$freq_limite = isset($_GET['frequencia']) && is_numeric($_GET['frequencia']) ? max(0, min(100, (float)$_GET['frequencia'])) : 75.0;
// Uma linha por matrícula; subconsultas independentes impedem multiplicação de notas por presenças.
$sql = "SELECT m.id_matricula, m.rm, m.id_turma, u.nome, t.nome AS turma_nome, t.ano_letivo,
 (SELECT AVG(n.nota) FROM nota n JOIN turma_disciplina td ON td.id_turma_disciplina=n.id_turma_disciplina WHERE n.id_matricula=m.id_matricula AND td.id_turma=m.id_turma AND n.nota IS NOT NULL) AS media,
 (SELECT COUNT(*) FROM nota n JOIN turma_disciplina td ON td.id_turma_disciplina=n.id_turma_disciplina WHERE n.id_matricula=m.id_matricula AND td.id_turma=m.id_turma AND n.nota IS NOT NULL) AS qtd_notas,
 (SELECT AVG(f.presente)*100 FROM frequencia f JOIN turma_disciplina td ON td.id_turma_disciplina=f.id_turma_disciplina WHERE f.id_matricula=m.id_matricula AND td.id_turma=m.id_turma) AS frequencia,
 (SELECT COUNT(*) FROM frequencia f JOIN turma_disciplina td ON td.id_turma_disciplina=f.id_turma_disciplina WHERE f.id_matricula=m.id_matricula AND td.id_turma=m.id_turma) AS qtd_aulas
 FROM matricula m JOIN usuario u ON u.id_usuario=m.id_aluno JOIN turma t ON t.id_turma=m.id_turma
 WHERE (?=0 OR m.id_turma=?) ORDER BY t.ano_letivo DESC,t.nome,u.nome";
$stmt = $conexao->prepare($sql);
$stmt->bind_param('ii', $id_turma, $id_turma);
$stmt->execute();
$res = $stmt->get_result();
$alunos=[]; $atencao=[]; $soma_notas=0; $qtd_medias=0; $soma_freq=0; $qtd_freq=0;
while ($a=$res->fetch_assoc()) {
 if ($a['media'] !== null) { $soma_notas+=(float)$a['media']; $qtd_medias++; }
 if ($a['frequencia'] !== null) { $soma_freq+=(float)$a['frequencia']; $qtd_freq++; }
 $a['alerta_nota']=$a['media'] !== null && (float)$a['media'] < $nota_limite;
 $a['alerta_freq']=$a['frequencia'] !== null && (float)$a['frequencia'] < $freq_limite;
 if ($a['alerta_nota'] || $a['alerta_freq']) $atencao[]=$a;
 $alunos[]=$a;
}
$stmt->close();
// Agregados por turma usam o mesmo conjunto de alunos, sem atribuir 100% a registros ausentes.
$grupos=[];
foreach ($alunos as $a) {
 $k=(int)$a['id_turma'];
 if (!isset($grupos[$k])) $grupos[$k]=['nome'=>$a['turma_nome'],'ano'=>$a['ano_letivo'],'id'=>$k,'total'=>0,'n'=>0,'soma'=>0,'f'=>0,'sf'=>0,'alertas'=>0];
 $grupos[$k]['total']++;
 if ($a['media'] !== null) { $grupos[$k]['n']++; $grupos[$k]['soma']+=(float)$a['media']; }
 if ($a['frequencia'] !== null) { $grupos[$k]['f']++; $grupos[$k]['sf']+=(float)$a['frequencia']; }
 if ($a['alerta_nota'] || $a['alerta_freq']) $grupos[$k]['alertas']++;
}
// Médias por disciplina: apenas notas efetivamente lançadas, sem inventar histórico.
$disciplinas=[];
$sd=$conexao->prepare("SELECT d.nome, AVG(n.nota) AS media, COUNT(n.id_nota) AS lancamentos FROM nota n JOIN turma_disciplina td ON td.id_turma_disciplina=n.id_turma_disciplina JOIN disciplina d ON d.id_disciplina=td.id_disciplina WHERE n.nota IS NOT NULL AND (?=0 OR td.id_turma=?) GROUP BY d.id_disciplina,d.nome ORDER BY d.nome");
$sd->bind_param('ii',$id_turma,$id_turma);$sd->execute();$rd=$sd->get_result();while($d=$rd->fetch_assoc())$disciplinas[]=$d;$sd->close();
?>
<!DOCTYPE html><html lang="pt-br"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Coordenação | Acompanhamento pedagógico</title><link rel="preconnect" href="https://fonts.googleapis.com"><link href="https://fonts.googleapis.com/css2?family=Inter:wght@400;500;600;700;800&display=swap" rel="stylesheet"><style>
