h:0;overflow:hidden;scroll-margin-top:20px}.panelhead{padding:20px 22px 17px;border-bottom:1px solid #eef0f6;display:flex;justify-content:space-between;align-items:center;gap:15px}.panelhead a{font-size:12px;color:#6554cf;font-weight:700;text-decoration:none;white-space:nowrap}.scroll{overflow-x:auto}table{width:100%;border-collapse:collapse;min-width:610px}th{text-align:left;background:#fafbfe;color:#697188;text-transform:uppercase;letter-spacing:.05em;font-size:10px}td,th{padding:13px 14px;border-bottom:1px solid #edf0f6;font-size:12px}tbody tr:last-child td{border-bottom:0}td a{color:#6554cf;font-weight:650;text-decoration:none}.pill{display:inline-block;padding:5px 8px;border-radius:8px;background:#f0edfd;color:#6245bc;font-weight:700;font-size:11px}.pill.warn{background:#fff0e2;color:#99521a}.pill.none{background:#f1f2f5;color:#797d8c}.empty{padding:30px;color:#7a7d8d;text-align:center;font-size:13px}.note{padding:16px 20px;color:#797d8c;font-size:11px;line-height:1.7;border-top:1px solid #eef0f6}.stack{display:grid;gap:16px}.barlist{padding:14px 21px 20px}.barrow{display:grid;grid-template-columns:minmax(95px,1fr) minmax(80px,1.5fr) 48px;align-items:center;gap:12px;padding:10px 0;font-size:12px}.barrow strong{text-align:right;font-size:12px}.track{height:9px;background:#edf0f6;border-radius:8px;overflow:hidden}.fill{height:100%;background:#6959d5;border-radius:8px}.subnav{display:flex;gap:10px;flex-wrap:wrap;margin-top:16px}.subnav a{font-size:12px;color:#6554cf;font-weight:700;text-decoration:none;background:#f1effd;border-radius:8px;padding:10px 13px}#menu .atlas-link-text{white-space:normal;overflow-wrap:anywhere;line-height:1.35}#menu a.atlas-link{white-space:normal;min-height:43px;padding-top:8px;padding-bottom:8px}body.atlas-collapsed #menu .atlas-link-text{display:none}@media(max-width:1100px){.dashboard{grid-template-columns:1fr}.summary{grid-template-columns:repeat(2,minmax(0,1fr))}}@media(max-width:650px){main{padding:68px 15px 35px}.summary{grid-template-columns:repeat(2,minmax(0,1fr));gap:9px}.metric{padding:15px}.metric strong{font-size:23px}.filters{padding:14px}.field{min-width:100%}.btn{width:100%}.tabs a{min-width:125px}.panelhead{padding:16px}.panelhead a{white-space:normal}.barrow{grid-template-columns:minmax(80px,1fr) minmax(65px,1fr) 42px;gap:7px}}
</style></head><body>
<?php include '../../includes/menu_coordenacao.php'; ?>
<main><header class="intro"><div class="eyebrow">Coordenação · Área pedagógica</div><h1>Acompanhamento pedagógico</h1><p class="muted">Acompanhe o desempenho das turmas, a frequência e os estudantes que precisam de atenção. Os indicadores usam somente os registros disponíveis no sistema.</p><div class="subnav"><a href="inicio_coordenacao.php">← Visão geral</a><a href="alunos_coordenacao.php">Consultar alunos</a><a href="professores_coordenacao.php">Consultar professores</a></div></header>
<nav class="tabs" aria-label="Seções do acompanhamento"><a href="#resumo">Visão geral</a><a href="#turmas">Desempenho das turmas</a><a href="#frequencia">Frequência</a><a href="#atencao">Alunos em atenção</a><a href="professores_coordenacao.php">Acompanhamento docente</a></nav>
<form class="card filters" method="get"><div class="field"><label for="turma">Turma</label><select id="turma" name="turma"><option value="0">Todas as turmas</option><?php foreach ($turmas as $t): ?><option value="<?= (int)$t['id_turma'] ?>" <?= $id_turma===(int)$t['id_turma']?'selected':'' ?>><?= esc($t['nome']) ?> · <?= esc($t['ano_letivo']) ?></option><?php endforeach; ?></select></div><div class="field"><label for="nota">Média abaixo de</label><input id="nota" type="number" name="nota" min="0" max="10" step="0.5" value="<?= esc($nota_limite) ?>"></div><div class="field"><label for="frequencia">Frequência abaixo de (%)</label><input id="frequencia" type="number" name="frequencia" min="0" max="100" step="1" value="<?= esc($freq_limite) ?>"></div><button class="btn" type="submit">Aplicar filtros</button></form>
<div class="summary" id="resumo"><div class="card metric"><span>Alunos matriculados</span><strong><?= count($alunos) ?></strong><span>Nas turmas selecionadas</span></div><div class="card metric"><span>Média das notas</span><strong><?= $qtd_medias?fmt($soma_notas/$qtd_medias,2):'—' ?></strong><span><?= $qtd_medias ?> aluno(s) com notas</span></div><div class="card metric"><span>Frequência média</span><strong><?= $qtd_freq?fmt($soma_freq/$qtd_freq).'%':'—' ?></strong><span><?= $qtd_freq ?> aluno(s) com presença</span></div><div class="card metric"><span>Alunos em atenção</span><strong><?= count($atencao) ?></strong><span>Segundo os limites acima</span></div></div>
<div class="dashboard"><div class="stack"><section class="card panel" id="turmas"><div class="panelhead"><div><h2>Desempenho das turmas</h2><p class="muted">Médias calculadas a partir dos registros disponíveis.</p></div><a href="alunos_coordenacao.php">Ver alunos →</a></div><?php if ($grupos): ?><div class="scroll"><table><thead><tr><th>Turma</th><th>Alunos</th><th>Média</th><th>Frequência</th><th>Em atenção</th><th></th></tr></thead><tbody><?php foreach ($grupos as $g): ?><tr><td><strong><?= esc($g['nome']) ?></strong><br><span class="muted"><?= esc($g['ano']) ?></span></td><td><?= $g['total'] ?></td><td><?= $g['n']?fmt($g['soma']/$g['n'],2):'—' ?></td><td><?= $g['f']?fmt($g['sf']/$g['f']).'%':'—' ?></td><td><span class="pill <?= $g['alertas']?'warn':'none' ?>"><?= $g['alertas'] ?></span></td><td><a href="alunos_coordenacao.php?turma=<?= $g['id'] ?>">Ver alunos</a></td></tr><?php endforeach; ?></tbody></table></div><?php else: ?><div class="empty">Não há matrículas para este filtro.</div><?php endif; ?></section>
<section class="card panel" id="atencao"><div class="panelhead"><div><h2>Alunos em atenção</h2><p class="muted">Notas ou frequência abaixo dos limites escolhidos.</p></div><a href="alunos_coordenacao.php">Consultar alunos →</a></div><?php if ($atencao): ?><div class="scroll"><table><thead><tr><th>Aluno</th><th>Turma</th><th>Média</th><th>Frequência</th><th>Motivo</th></tr></thead><tbody><?php foreach (array_slice($atencao,0,12) as $a): ?><tr><td><strong><?= esc($a['nome']) ?></strong><br><span class="muted">RM <?= esc($a['rm']) ?></span></td><td><?= esc($a['turma_nome']) ?></td><td><?= $a['media']!==null?fmt($a['media'],2):'—' ?></td><td><?= $a['frequencia']!==null?fmt($a['frequencia']).'%':'—' ?></td><td><?php if ($a['alerta_nota']): ?><span class="pill warn">Nota</span> <?php endif; ?><?php if ($a['alerta_freq']): ?><span class="pill warn">Frequência</span><?php endif; ?></td></tr><?php endforeach; ?></tbody></table></div><?php if(count($atencao)>12): ?><div class="note">Mostrando 12 de <?= count($atencao) ?> alunos. Selecione uma turma no filtro para restringir a lista.</div><?php endif; ?><?php else: ?><div class="empty">Nenhum aluno atende aos critérios com os dados disponíveis.</div><?php endif; ?></section></div>
<div class="stack"><section class="card panel"><div class="panelhead"><div><h2>Médias por disciplina</h2><p class="muted">Média das notas lançadas por disciplina.</p></div></div><?php if($disciplinas): ?><div class="barlist"><?php foreach($disciplinas as $d): ?><div class="barrow"><span><?= esc($d['nome']) ?></span><div class="track"><div class="fill" style="width:<?= max(0,min(100,(float)$d['media']*10)) ?>%"></div></div><strong><?= fmt($d['media'],2) ?></strong></div><?php endforeach; ?></div><?php else: ?><div class="empty">Sem notas lançadas.</div><?php endif; ?></section>
<section class="card panel" id="frequencia"><div class="panelhead"><div><h2>Frequência por turma</h2><p class="muted">Média da frequência individual registrada.</p></div></div><?php if($grupos): ?><div class="barlist"><?php foreach($grupos as $g): ?><div class="barrow"><span><?= esc($g['nome']) ?></span><div class="track"><div class="fill" style="width:<?= $g['f']?max(0,min(100,$g['sf']/$g['f'])):0 ?>%"></div></div><strong><?= $g['f']?fmt($g['sf']/$g['f']).'%':'—' ?></strong></div><?php endforeach; ?></div><?php else: ?><div class="empty">Sem turmas para exibir.</div><?php endif; ?></section></div></div>
<p class="note">Os limites de 6,0 e 75% são filtros de exemplo, não regras oficiais da escola. Alunos sem notas ou frequência registradas não são automaticamente classificados. Não há comparação com períodos anteriores porque esses dados não foram calculados.</p>
</main></body></html>
